17.query:
SELECT SUM(observed_merchandise_value) FILTER(WHERE delivered_orders >= 2) / NULLIF(SUM(observed_merchandise_value), 0) AS "Merchandise share from repeat customers" 
FROM (SELECT * FROM reporting.analytic_customers WHERE release_id='87f01740-0523-5fd4-be0e-eb52acb2842a'
) AS virtual_table 
 LIMIT 1000;

16.query:
SELECT CAST(COUNT(*) FILTER(WHERE delivered_orders >= 2) AS DECIMAL) / NULLIF(COUNT(*), 0) AS "Repeat customer share" 
FROM (SELECT * FROM reporting.analytic_customers WHERE release_id='87f01740-0523-5fd4-be0e-eb52acb2842a'
) AS virtual_table 
 LIMIT 1000;

40.query:
SELECT month_offset AS month_offset, CAST(SUM(active_customers) AS DECIMAL) / NULLIF(SUM(cohort_size), 0) AS "Observed return rate · months 1–6, eligible cohorts" 
FROM (SELECT *,cohort_month::text AS cohort_label FROM reporting.analytic_cohorts WHERE release_id='87f01740-0523-5fd4-be0e-eb52acb2842a'
) AS virtual_table 
WHERE month_offset > 0 AND cohort_label >= '2017-01-01' GROUP BY month_offset ORDER BY "Observed return rate · months 1–6, eligible cohorts" DESC 
 LIMIT 1000;

19.query:
SELECT recency_segment AS recency_segment, COUNT(*) AS "Recency at 31 Aug 2018 · customers" 
